function validate([nums, l, r]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v < -1000 || v > 1000)) return 'Each value is between -1000 and 1000.';
  if (!(1 <= l && l <= r && r <= nums.length)) return 'Need 1 <= l <= r <= nums.length.';
  return null;
}

