function minimumSumSubarray(nums, l, r) {
  const positive = [];
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const length = j - i + 1;
      if (length < l || length > r) continue;
      let total = 0;
      for (let k = i; k <= j; k++) total += nums[k];
      if (total > 0) positive.push(total);
    }
  }
  return positive.length ? Math.min(...positive) : -1;
}

