function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' || rand() < 0.15 ? 1000 : 1 + Math.floor(rand() * 10);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  const l = 1 + Math.floor(rand() * n);
  const r = l + Math.floor(rand() * (n - l + 1));
  return [nums, l, r];
}
